"""Self-contained XGBoost solution. Change this file; use evaluate.py to test."""
import numpy as np
import pandas as pd
import xgboost as xgb

CFG = {
    # low-cardinality columns passed as native XGBoost categoricals
    "cats": ["advisory_committee", "device_class", "clearance_type", "third_party_flag", "applicant_country_code"],
    "nums": ["review_days", "applicant_prior_clearances"],
    # smoothed out-of-fold target encodings; each key is a tuple of columns
    "te": [("product_code",)],
    # label-free training frequency of a key
    "freq": [("product_code",)],
    "te_m": 20.0,          # smoothing pseudo-count towards the prior
    "folds": 5,            # contiguous (chronological row order) blocks for OOF encodings
    "fold_mode": "block",  # "block" or "random"
    "params": {"n_estimators": 300, "max_depth": 4, "learning_rate": 0.03, "min_child_weight": 5,
               "subsample": 0.8, "colsample_bytree": 0.8, "reg_lambda": 5.0, "max_cat_to_onehot": 1,
               "max_cat_threshold": 16},
}


def _key(X, cols):
    s = X[cols[0]].astype(str)
    for c in cols[1:]:
        s = s + "|" + X[c].astype(str)
    return s


def _name(prefix, cols):
    return prefix + "_" + "+".join(cols)


def fit(X_train, y_train, *, seed, threads, cfg=None):
    cfg = dict(CFG if cfg is None else cfg)
    X = X_train.reset_index(drop=True)
    y = np.asarray(y_train, dtype=float)
    n = len(X)
    prior = float(y.mean())
    m = float(cfg["te_m"])
    levels = {c: pd.Index(sorted(X[c].dropna().astype(str).unique())) for c in cfg["cats"]}
    state = {"cfg": cfg, "levels": levels, "prior": prior, "te": {}, "freq": {}}
    # fold assignment for out-of-fold target statistics (a row never sees its own label)
    k = int(cfg["folds"])
    if cfg["fold_mode"] == "block":
        fold = (np.arange(n) * k // n).astype(int)  # rows arrive in chronological order
    else:
        fold = np.random.RandomState(seed).randint(0, k, n)
    oof = {}
    for cols in cfg["te"]:
        key = _key(X, cols)
        d = pd.DataFrame({"k": key.to_numpy(), "y": y, "f": fold})
        tot = d.groupby("k")["y"].agg(["sum", "count"])
        state["te"][cols] = {kk: (float(s) + m * prior) / (float(c) + m) for kk, s, c in zip(tot.index, tot["sum"], tot["count"])}
        enc = np.empty(n)
        for f in range(k):
            inm = fold == f
            yo = y[~inm]
            pf = float(yo.mean())  # prior also excludes the held-out fold's labels
            g = d[~inm].groupby("k")["y"].agg(["sum", "count"])
            s = d.loc[inm, "k"].map(g["sum"]).fillna(0.0).to_numpy()
            c = d.loc[inm, "k"].map(g["count"]).fillna(0.0).to_numpy()
            enc[inm] = (s + m * pf) / (c + m)
        oof[_name("te", cols)] = enc
    for cols in cfg["freq"]:
        key = _key(X, cols)
        vc = key.value_counts()
        state["freq"][cols] = {kk: float(v) / n for kk, v in zip(vc.index, vc.values)}
    F = prepare(state, X)
    for name, enc in oof.items():
        F[name] = enc
    model = xgb.XGBClassifier(tree_method="hist", enable_categorical=True, random_state=seed, n_jobs=threads,
                              **cfg["params"])
    model.fit(F, y_train)
    state["model"] = model
    return state


def prepare(state, X):
    cfg = state["cfg"]
    out = {}
    for c in cfg["nums"]:
        out[c] = pd.to_numeric(X[c], errors="coerce").to_numpy(dtype=float)
    for c in cfg["cats"]:
        out[c] = pd.Categorical(X[c].astype(str).where(X[c].notna()), categories=state["levels"][c])
    for cols in cfg["te"]:
        t = state["te"][cols]
        p = state["prior"]
        out[_name("te", cols)] = np.array([t.get(kk, p) for kk in _key(X, cols)], dtype=float)
    for cols in cfg["freq"]:
        t = state["freq"][cols]
        out[_name("freq", cols)] = np.array([t.get(kk, 0.0) for kk in _key(X, cols)], dtype=float)
    return pd.DataFrame(out)


def predict(model, X):
    return model["model"].predict_proba(prepare(model, X))[:, 1]

