"""Self-contained XGBoost solution. Change this file; use evaluate.py to test.

Features are built only from the permitted predictor columns. Learned state
(category rates, counts) comes from the fitting partition only; training rows
receive out-of-fold target encodings so a row's own label never enters its
encoding (including priors, which are computed on the same out-of-fold rows).
"""
import numpy as np
import pandas as pd
import xgboost as xgb

CFG = {
    "params": {"n_estimators": 400, "max_depth": 4, "learning_rate": 0.03,
               "subsample": 0.8, "colsample_bytree": 0.7, "min_child_weight": 5,
               "reg_lambda": 5.0, "gamma": 0.0},
    "te": [("product_code",), ("advisory_committee",), ("applicant_country_code",),
           ("product_code", "clearance_type")],
    "te_m": 20.0,
    "folds": 5,
    "counts": [("product_code",), ("applicant_country_code",)],
    "recency": 0.0,      # weight = exp(recency * (rank - 1)), rank in [0, 1] by training row order
    "pc_letters": False,
    "num_te": [],        # numeric columns for binned target encoding
}

CAT_MAPS = {
    "device_class": {"1": 1.0, "2": 2.0, "3": 3.0, "U": 0.0},
    "clearance_type": {"Traditional": 0.0, "Special": 1.0, "Abbreviated": 2.0},
    "third_party_flag": {"N": 0.0, "Y": 1.0},
}


def _key(X, cols):
    k = X[cols[0]].astype("string").fillna("<NA>").astype(object)
    for c in cols[1:]:
        k = k + "|" + X[c].astype("string").fillna("<NA>").astype(object)
    return k.to_numpy()


def _stats(keys, y):
    d = pd.DataFrame({"k": keys, "y": y}).groupby("k").y.agg(["sum", "count"])
    return dict(zip(d.index, zip(d["sum"].to_numpy(float), d["count"].to_numpy(float))))


def _encode(keys, stats, prior, m):
    out = np.empty(len(keys))
    for i, k in enumerate(keys):
        s, n = stats.get(k, (0.0, 0.0))
        out[i] = (s + m * prior) / (n + m)
    return out


def _base(state, X):
    cfg = state["cfg"]
    f = {}
    f["review_days"] = X["review_days"].to_numpy(float)
    f["prior_clear"] = X["applicant_prior_clearances"].to_numpy(float)
    for c, mp in CAT_MAPS.items():
        f[c] = X[c].astype("string").map(mp).astype(float).to_numpy()
    ac = X["advisory_committee"].astype("string")
    f["ac_code"] = ac.map(state["ac_codes"]).astype(float).to_numpy()
    f["is_us"] = (X["applicant_country_code"].astype("string") == "US").astype(float).to_numpy()
    for cols in cfg["counts"]:
        cnt = state["counts"]["|".join(cols)]
        f["cnt_" + "_".join(cols)] = np.array([cnt.get(k, 0.0) for k in _key(X, cols)])
    if cfg["pc_letters"]:
        pc = X["product_code"].astype("string").fillna("???")
        for j in range(3):
            f["pc_l%d" % j] = pc.str[j].map(lambda ch: float(ord(ch)) if isinstance(ch, str) else np.nan).astype(float).to_numpy()
    return f


def _te_features(state, X, stats_all):
    cfg = state["cfg"]
    f = {}
    for cols in cfg["te"]:
        name = "|".join(cols)
        stats, prior = stats_all[name]
        f["te_" + "_".join(cols)] = _encode(_key(X, cols), stats, prior, cfg["te_m"])
    return f


def _frame(state, f):
    return pd.DataFrame({c: f[c] for c in state["feature_names"]})[state["feature_names"]].astype(float)


def fit(X_train, y_train, *, seed, threads):
    cfg = dict(CFG)
    X = X_train.reset_index(drop=True)
    y = np.asarray(y_train).astype(float)
    n = len(X)
    state = {"cfg": cfg}
    state["ac_codes"] = {v: float(i) for i, v in enumerate(sorted(X["advisory_committee"].dropna().astype(str).unique()))}
    state["counts"] = {}
    for cols in cfg["counts"]:
        vc = pd.Series(_key(X, cols)).value_counts()
        state["counts"]["|".join(cols)] = {k: float(v) for k, v in vc.items()}
    # Full-train target statistics (used only for unseen rows in prepare).
    state["te"] = {}
    for cols in cfg["te"]:
        state["te"]["|".join(cols)] = (_stats(_key(X, cols), y), float(y.mean()))
    # Out-of-fold encodings for training rows.
    rng = np.random.RandomState(seed)
    fold = rng.randint(0, cfg["folds"], size=n)
    oof = {}
    for k in range(cfg["folds"]):
        tr = fold != k
        te = np.where(~tr)[0]
        stats_k = {}
        Xtr = X.iloc[np.where(tr)[0]]
        for cols in cfg["te"]:
            stats_k["|".join(cols)] = (_stats(_key(Xtr, cols), y[tr]), float(y[tr].mean()))
        fk = _te_features(state, X.iloc[te], stats_k)
        for c, v in fk.items():
            oof.setdefault(c, np.empty(n))[te] = v
    f = _base(state, X)
    f.update(oof)
    state["feature_names"] = list(f.keys())
    w = None
    if cfg["recency"]:
        rank = np.arange(n) / max(1, n - 1)
        w = np.exp(cfg["recency"] * (rank - 1.0))
    m = xgb.XGBClassifier(tree_method="hist", random_state=seed, n_jobs=threads,
                          eval_metric="logloss", **cfg["params"])
    m.fit(_frame(state, f), y, sample_weight=w)
    state["model"] = m
    return state


def prepare(state, X):
    X = X.reset_index(drop=True)
    f = _base(state, X)
    f.update(_te_features(state, X, state["te"]))
    return _frame(state, f)


def predict(model, X):
    return model["model"].predict_proba(prepare(model, X))[:, 1]

