    return state


def prepare(state, X):
    cols = _base(state, X)
    for (kc, pk, sm), (tab, ptab) in zip(state["cfg"]["te"], state["te"]):
        cols.append(_enc(tab, ptab, _keys(X, kc), _keys(X, pk) if pk else None, state["prior"], sm))
